PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE `_migrations` (file VARCHAR(255) PRIMARY KEY NOT NULL, applied INTEGER NOT NULL);
CREATE TABLE `_params` (
			`id`      TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL,
			`value`   JSON DEFAULT NULL,
			`created` TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ')) NOT NULL,
			`updated` TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ')) NOT NULL
		);
CREATE TABLE `_collections` (
				`id`         TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL,
				`system`     BOOLEAN DEFAULT FALSE NOT NULL,
				`type`       TEXT DEFAULT "base" NOT NULL,
				`name`       TEXT UNIQUE NOT NULL,
				`fields`     JSON DEFAULT "[]" NOT NULL,
				`indexes`    JSON DEFAULT "[]" NOT NULL,
				`listRule`   TEXT DEFAULT NULL,
				`viewRule`   TEXT DEFAULT NULL,
				`createRule` TEXT DEFAULT NULL,
				`updateRule` TEXT DEFAULT NULL,
				`deleteRule` TEXT DEFAULT NULL,
				`options`    JSON DEFAULT "{}" NOT NULL,
				`created`    TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ')) NOT NULL,
				`updated`    TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ')) NOT NULL
			);
CREATE TABLE `_mfas` (`collectionRef` TEXT DEFAULT '' NOT NULL, `created` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `method` TEXT DEFAULT '' NOT NULL, `recordRef` TEXT DEFAULT '' NOT NULL, `updated` TEXT DEFAULT '' NOT NULL);
ANALYZE sqlite_schema;
ANALYZE sqlite_schema;
CREATE TABLE `_otps` (`collectionRef` TEXT DEFAULT '' NOT NULL, `created` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `password` TEXT DEFAULT '' NOT NULL, `recordRef` TEXT DEFAULT '' NOT NULL, `sentTo` TEXT DEFAULT '' NOT NULL, `updated` TEXT DEFAULT '' NOT NULL);
CREATE TABLE `_externalAuths` (`collectionRef` TEXT DEFAULT '' NOT NULL, `created` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `provider` TEXT DEFAULT '' NOT NULL, `providerId` TEXT DEFAULT '' NOT NULL, `recordRef` TEXT DEFAULT '' NOT NULL, `updated` TEXT DEFAULT '' NOT NULL);
CREATE TABLE `_authOrigins` (`collectionRef` TEXT DEFAULT '' NOT NULL, `created` TEXT DEFAULT '' NOT NULL, `fingerprint` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `recordRef` TEXT DEFAULT '' NOT NULL, `updated` TEXT DEFAULT '' NOT NULL);
CREATE TABLE `_superusers` (`created` TEXT DEFAULT '' NOT NULL, `email` TEXT DEFAULT '' NOT NULL, `emailVisibility` BOOLEAN DEFAULT FALSE NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `password` TEXT DEFAULT '' NOT NULL, `tokenKey` TEXT DEFAULT '' NOT NULL, `updated` TEXT DEFAULT '' NOT NULL, `verified` BOOLEAN DEFAULT FALSE NOT NULL);
CREATE TABLE `users` (`avatar` TEXT DEFAULT '' NOT NULL, `created` TEXT DEFAULT '' NOT NULL, `email` TEXT DEFAULT '' NOT NULL, `emailVisibility` BOOLEAN DEFAULT FALSE NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `name` TEXT DEFAULT '' NOT NULL, `password` TEXT DEFAULT '' NOT NULL, `tokenKey` TEXT DEFAULT '' NOT NULL, `updated` TEXT DEFAULT '' NOT NULL, `verified` BOOLEAN DEFAULT FALSE NOT NULL, "role" TEXT DEFAULT '' NOT NULL, "employee" TEXT DEFAULT '' NOT NULL, "points" NUMERIC DEFAULT 0 NOT NULL, "first_name" TEXT DEFAULT '' NOT NULL, "last_name" TEXT DEFAULT '' NOT NULL);
CREATE TABLE `shift_templates` (`color` TEXT DEFAULT '' NOT NULL, `department` TEXT DEFAULT '' NOT NULL, `end_time` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `name` TEXT DEFAULT '' NOT NULL, `sort_order` NUMERIC DEFAULT 0 NOT NULL, `start_time` TEXT DEFAULT '' NOT NULL);
CREATE TABLE `departments` (`color` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `name` TEXT DEFAULT '' NOT NULL, `sort_order` NUMERIC DEFAULT 0 NOT NULL);
CREATE TABLE `employees` (`active` BOOLEAN DEFAULT FALSE NOT NULL, `birthday` TEXT DEFAULT '' NOT NULL, `city` TEXT DEFAULT '' NOT NULL, `contract_type` TEXT DEFAULT '' NOT NULL, `department` TEXT DEFAULT '' NOT NULL, `email` TEXT DEFAULT '' NOT NULL, `end_date` TEXT DEFAULT '' NOT NULL, `first_name` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `last_name` TEXT DEFAULT '' NOT NULL, `phone` TEXT DEFAULT '' NOT NULL, `position` TEXT DEFAULT '' NOT NULL, `start_date` TEXT DEFAULT '' NOT NULL, `street` TEXT DEFAULT '' NOT NULL, `vacation_days` NUMERIC DEFAULT 0 NOT NULL, `weekly_hours` NUMERIC DEFAULT 0 NOT NULL, `zip` TEXT DEFAULT '' NOT NULL, "planner_departments" JSON DEFAULT NULL);
CREATE TABLE `settings` (`id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `key` TEXT DEFAULT '' NOT NULL, `value` TEXT DEFAULT '' NOT NULL);
CREATE TABLE `absences` (`approved_at` TEXT DEFAULT '' NOT NULL, `approved_by` TEXT DEFAULT '' NOT NULL, `created_by` TEXT DEFAULT '' NOT NULL, `date_from` TEXT DEFAULT '' NOT NULL, `date_to` TEXT DEFAULT '' NOT NULL, `document` TEXT DEFAULT '' NOT NULL, `employee` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `note` TEXT DEFAULT '' NOT NULL, `status` TEXT DEFAULT '' NOT NULL, `type` TEXT DEFAULT '' NOT NULL, "push_notified" BOOLEAN DEFAULT FALSE NOT NULL);
CREATE TABLE `availability` (`available` BOOLEAN DEFAULT FALSE NOT NULL, `day_of_week` NUMERIC DEFAULT 0 NOT NULL, `employee` TEXT DEFAULT '' NOT NULL, `from_time` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `to_time` TEXT DEFAULT '' NOT NULL);
CREATE TABLE `documents` (`date` TEXT DEFAULT '' NOT NULL, `employee` TEXT DEFAULT '' NOT NULL, `file` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `name` TEXT DEFAULT '' NOT NULL, `type` TEXT DEFAULT '' NOT NULL, `uploaded_by` TEXT DEFAULT '' NOT NULL);
CREATE TABLE `notifications` (`id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `message` TEXT DEFAULT '' NOT NULL, `read` BOOLEAN DEFAULT FALSE NOT NULL, `reference_id` TEXT DEFAULT '' NOT NULL, `title` TEXT DEFAULT '' NOT NULL, `type` TEXT DEFAULT '' NOT NULL, `user` TEXT DEFAULT '' NOT NULL);
CREATE TABLE `time_entries` (`break_minutes` NUMERIC DEFAULT 0 NOT NULL, `corrected_by` TEXT DEFAULT '' NOT NULL, `employee` TEXT DEFAULT '' NOT NULL, `end_time` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `note` TEXT DEFAULT '' NOT NULL, `start_time` TEXT DEFAULT '' NOT NULL);
CREATE TABLE `vacation_accounts` (`carry_over` NUMERIC DEFAULT 0 NOT NULL, `carry_over_expires` TEXT DEFAULT '' NOT NULL, `employee` TEXT DEFAULT '' NOT NULL, `entitlement` NUMERIC DEFAULT 0 NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `year` NUMERIC DEFAULT 0 NOT NULL);
CREATE TABLE `gam_tasks` (`active` BOOLEAN DEFAULT FALSE NOT NULL, `category` TEXT DEFAULT '' NOT NULL, `created_by` TEXT DEFAULT '' NOT NULL, `daily_limit_per_user` NUMERIC DEFAULT 0 NOT NULL, `description` TEXT DEFAULT '' NOT NULL, `difficulty` TEXT DEFAULT '' NOT NULL, `expires_at` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `points` NUMERIC DEFAULT 0 NOT NULL, `priority` TEXT DEFAULT '' NOT NULL, `requires_media` BOOLEAN DEFAULT FALSE NOT NULL, `tags` TEXT DEFAULT '' NOT NULL, `time_limit_minutes` NUMERIC DEFAULT 0 NOT NULL, `title` TEXT DEFAULT '' NOT NULL, created TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ', 'now')), updated TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ', 'now')));
CREATE TABLE `gam_assignments` (`expires_at` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `rejected_at` TEXT DEFAULT '' NOT NULL, `status` TEXT DEFAULT '' NOT NULL, `task_id` TEXT DEFAULT '' NOT NULL, `user_id` TEXT DEFAULT '' NOT NULL, created TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ', 'now')), updated TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ', 'now')));
CREATE TABLE `gam_submissions` (`admin_feedback` TEXT DEFAULT '' NOT NULL, `approved_at` TEXT DEFAULT '' NOT NULL, `assignment_id` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `media_url` TEXT DEFAULT '' NOT NULL, `points_awarded` NUMERIC DEFAULT 0 NOT NULL, `status` TEXT DEFAULT '' NOT NULL, `submission_notes` TEXT DEFAULT '' NOT NULL, `task_id` TEXT DEFAULT '' NOT NULL, `user_id` TEXT DEFAULT '' NOT NULL, created TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ', 'now')), updated TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ', 'now')));
CREATE TABLE `gam_rewards` (`available_from` TEXT DEFAULT '' NOT NULL, `available_until` TEXT DEFAULT '' NOT NULL, `category` TEXT DEFAULT '' NOT NULL, `code_pool` JSON DEFAULT NULL, `created_by` TEXT DEFAULT '' NOT NULL, `description` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `max_redemptions` NUMERIC DEFAULT 0 NOT NULL, `points_cost` NUMERIC DEFAULT 0 NOT NULL, `redemption_type` TEXT DEFAULT '' NOT NULL, `redemptions_count` NUMERIC DEFAULT 0 NOT NULL, `status` TEXT DEFAULT '' NOT NULL, `title` TEXT DEFAULT '' NOT NULL, created TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ', 'now')), updated TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ', 'now')));
CREATE TABLE `gam_orders` (`admin_feedback` TEXT DEFAULT '' NOT NULL, `approved_at` TEXT DEFAULT '' NOT NULL, `code_assigned` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `reward_id` TEXT DEFAULT '' NOT NULL, `status` TEXT DEFAULT '' NOT NULL, `user_id` TEXT DEFAULT '' NOT NULL, created TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ', 'now')), updated TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ', 'now')));
CREATE TABLE `gam_events` (`data` JSON DEFAULT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `related_reward_id` TEXT DEFAULT '' NOT NULL, `related_task_id` TEXT DEFAULT '' NOT NULL, `type` TEXT DEFAULT '' NOT NULL, `user_id` TEXT DEFAULT '' NOT NULL, created TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ', 'now')), updated TEXT DEFAULT (strftime('%Y-%m-%d %H:%M:%fZ', 'now')));
CREATE TABLE `gam_settings` (`enabled` BOOLEAN DEFAULT FALSE NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `updated_by` TEXT DEFAULT '' NOT NULL, created TEXT, updated TEXT);
CREATE TABLE `push_subscriptions` (`auth` TEXT DEFAULT '' NOT NULL, `employee` TEXT DEFAULT '' NOT NULL, `endpoint` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `p256dh` TEXT DEFAULT '' NOT NULL, `user_agent` TEXT DEFAULT '' NOT NULL);
CREATE TABLE `shift_plans` (`created_by` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `push_notified` BOOLEAN DEFAULT FALSE NOT NULL, `status` TEXT DEFAULT '' NOT NULL, `week_end` TEXT DEFAULT '' NOT NULL, `week_start` TEXT DEFAULT '' NOT NULL);
CREATE TABLE `shift_entries` (`color` TEXT DEFAULT '' NOT NULL, `color2` TEXT DEFAULT '' NOT NULL, `date` TEXT DEFAULT '' NOT NULL, `department` TEXT DEFAULT '' NOT NULL, `employee` TEXT DEFAULT '' NOT NULL, `end_time` TEXT DEFAULT '' NOT NULL, `end_time2` TEXT DEFAULT '' NOT NULL, `id` TEXT PRIMARY KEY DEFAULT ('r'||lower(hex(randomblob(7)))) NOT NULL, `is_open` BOOLEAN DEFAULT FALSE NOT NULL, `note` TEXT DEFAULT '' NOT NULL, `note2` TEXT DEFAULT '' NOT NULL, `plan_id` TEXT DEFAULT '' NOT NULL, `start_time` TEXT DEFAULT '' NOT NULL, `start_time2` TEXT DEFAULT '' NOT NULL, `status` TEXT DEFAULT '' NOT NULL, "is_free_day" BOOLEAN DEFAULT FALSE NOT NULL);
CREATE INDEX idx__collections_type on `_collections` (`type`);
CREATE INDEX `idx_mfas_collectionRef_recordRef` ON `_mfas` (
  `collectionRef`,
  `recordRef`
);
CREATE INDEX `idx_otps_collectionRef_recordRef` ON `_otps` (
  `collectionRef`,
  `recordRef`
);
CREATE UNIQUE INDEX `idx_externalAuths_record_provider` ON `_externalAuths` (
  `collectionRef`,
  `recordRef`,
  `provider`
);
CREATE UNIQUE INDEX `idx_externalAuths_collection_provider` ON `_externalAuths` (
  `collectionRef`,
  `provider`,
  `providerId`
);
CREATE UNIQUE INDEX `idx_authOrigins_unique_pairs` ON `_authOrigins` (
  `collectionRef`,
  `recordRef`,
  `fingerprint`
);
CREATE UNIQUE INDEX `idx_tokenKey_pbc_3142635823` ON `_superusers` (`tokenKey`);
CREATE UNIQUE INDEX `idx_email_pbc_3142635823` ON `_superusers` (`email`) WHERE `email` != '';
CREATE UNIQUE INDEX `idx_shift_templates_dept_name` ON `shift_templates` (
  `department`,
  `name`
);
CREATE INDEX `idx_gam_assignments_user_status_expires` ON `gam_assignments` (
  `user_id`,
  `status`,
  `expires_at`
);
CREATE INDEX `idx_gam_submissions_user_status` ON `gam_submissions` (
  `user_id`,
  `status`
);
CREATE INDEX `idx_gam_events_user` ON `gam_events` (`user_id`);
CREATE UNIQUE INDEX `idx_tokenKey__pb_users_auth_` ON `users` (`tokenKey`);
CREATE UNIQUE INDEX `idx_email__pb_users_auth_` ON `users` (`email`) WHERE `email` != '';
COMMIT;
